mapper.update:
UPDATE appointment
visit_reason = #{visitReason}, visit_start_time = #{visitStartTime}, visit_end_time = #{visitEndTime}, visitor_count = #{visitorCount}, remark = #{remark}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT a.* FROM appointment a

    INNER JOIN sys_user u ON a.host_user_id = u.id


    AND a.host_user_id = #{hostUserId}
    AND a.created_by = #{createdBy}
    AND u.department = #{department}
    AND a.status = #{status}

ORDER BY a.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM appointment a

    INNER JOIN sys_user u ON a.host_user_id = u.id


    AND a.host_user_id = #{hostUserId}
    AND a.created_by = #{createdBy}
    AND u.department = #{department}
    AND a.status = #{status}

SELECT * FROM appointment
WHERE visitor_id = #{visitorId}
  AND status IN ('PENDING_APPROVAL', 'APPROVED')
  AND visit_start_time < #{endTime}
  AND visit_end_time > #{startTime}
  AND id != #{excludeId}

SELECT a.* FROM appointment a

    INNER JOIN sys_user u ON a.host_user_id = u.id

WHERE a.status = 'PENDING_APPROVAL'
AND u.department = #{department}
ORDER BY a.created_at ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM appointment a
INNER JOIN sys_user u ON a.host_user_id = u.id
WHERE a.status = 'PENDING_APPROVAL' AND u.department = #{department}
